package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

type persistentRefBuilder func() (newHash, expectedHash plumbing.Hash, err error)

func repositoryDirs(ctx context.Context, repo *git.Repository) (worktreeRoot, commonDir string, err error) {
	wt, err := repo.Worktree()
	if err != nil {
		return "", "", fmt.Errorf("open worktree: %w", err)
	}
	worktreeRoot = wt.Filesystem().Root()
	if worktreeRoot == "" {
		return "", "", errors.New("repository worktree filesystem has no root path")
	}
	commonDir, err = resolveGitCommonDir(ctx, repo)
	if err != nil {
		return "", "", err
	}
	return worktreeRoot, commonDir, nil
}

// casUpdateRef atomically updates refName through native Git's lock protocol.
// Pass ZeroHash as expectedHash to require that the ref does not exist.
func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
	newValue := newHash.String()
	oldValue := strings.Repeat("0", newHash.HexSize())
	if expectedHash != plumbing.ZeroHash {
		oldValue = expectedHash.String()
	}

	cmd := exec.CommandContext(ctx, "git", "update-ref", refName.String(), newValue, oldValue)
	cmd.Dir = repoRoot
	cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")
	output, err := cmd.CombinedOutput()
	if err == nil {
		return nil
	}

	if isPersistentRefBusy(output) {
		return ErrShadowRefBusy
	}
	return fmt.Errorf("git update-ref %s: %s: %w", refName, strings.TrimSpace(string(output)), err)
}

func isPersistentRefBusy(stderr []byte) bool {
	if gitrepo.IsRefCASConflict(stderr) {
		return true
	}
	msg := strings.ToLower(string(stderr))
	return strings.Contains(msg, ".lock") && strings.Contains(msg, "file exists")
}

func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create persistent ref lock directory: %w", err)
	}
	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
	return filepath.Join(lockDir, safe+".lock"), nil
}

func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
	path, err := persistentRefLockPath(commonDir, refName)
	if err != nil {
		return err
	}
	release, err := flock.AcquireContext(ctx, path)
	if err != nil {
		return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
	}
	defer release()
	return fn()
}

func withLockedPersistentRef(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	fn func(repoRoot, commonDir string) error,
) error {
	repoRoot, commonDir, err := repositoryDirs(ctx, repo)
	if err != nil {
		return fmt.Errorf("resolve repository directories: %w", err)
	}
	return withPersistentRefFlock(ctx, commonDir, refName, func() error {
		return fn(repoRoot, commonDir)
	})
}

// CASPersistentRef serializes with Entire's persistent ref writers and updates
// refName through native Git's cross-process compare-and-swap protocol.
func CASPersistentRef(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	newHash, expectedHash plumbing.Hash,
) error {
	return withLockedPersistentRef(ctx, repo, refName, func(repoRoot, _ string) error {
		return casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
	})
}

// updatePersistentRef serializes Entire writers for one ref and retains a CAS
// retry for native Git or other external writers. build runs again after every
// conflict, so each retry reconstructs its tree and commit from the fresh tip.
func updatePersistentRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, build persistentRefBuilder) error {
	return withLockedPersistentRef(ctx, repo, refName, func(repoRoot, commonDir string) error {
		for attempt := range shadowRefMaxRetries {
			newHash, expectedHash, buildErr := build()
			if buildErr != nil {
				return buildErr
			}

			refErr := casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
			if refErr == nil {
				return nil
			}
			if !errors.Is(refErr, ErrShadowRefBusy) {
				return fmt.Errorf("update persistent ref %s: %w", refName, refErr)
			}
			if newHash != expectedHash {
				tryDeleteLooseObject(commonDir, newHash)
			}

			if backoffErr := shadowRefBackoff(ctx, attempt); backoffErr != nil {
				return backoffErr
			}
		}

		logging.Warn(logging.WithComponent(ctx, "checkpoint"),
			"persistent ref CAS retry budget exhausted",
			slog.String("ref", refName.String()),
			slog.Int("retries", shadowRefMaxRetries),
		)
		return fmt.Errorf("failed to update persistent ref %s after %d CAS retries: %w", refName, shadowRefMaxRetries, ErrShadowRefBusy)
	})
}
package gitrepo

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/storer"
	gogitstorage "github.com/go-git/go-git/v6/storage"
	gitfilesystem "github.com/go-git/go-git/v6/storage/filesystem"
)

// reftableGitTimeout bounds each git plumbing invocation the reftable storer
// makes. Ref reads/writes against the local reftable stack are fast; the
// timeout only guards against a wedged git process.
const reftableGitTimeout = 30 * time.Second

// repoUsesReftable reports whether the repository at the given git directories
// stores its references using the reftable backend rather than the classic
// loose-files + packed-refs layout.
//
// go-git (through the vendored v6 alpha) has no reftable reader: its filesystem
// storer reads refs from .git/refs, .git/packed-refs and .git/HEAD, none of
// which are authoritative in a reftable repository. Detection lets us route ref
// operations through the git CLI instead (see reftableStorer).
//
// A reftable repository is identified by the presence of a "reftable/"
// directory under either the worktree git dir or the common git dir. Git 2.45+
// creates this directory for `git init --ref-format=reftable` and for
// `git refs migrate --ref-format=reftable`. Checking the directory avoids
// parsing config and works for linked worktrees, where the shared stack lives
// under the common git dir.
func repoUsesReftable(dotGitPath, commonGitPath string) bool {
	candidates := []string{filepath.Join(dotGitPath, "reftable")}
	if commonGitPath != "" && commonGitPath != dotGitPath {
		candidates = append(candidates, filepath.Join(commonGitPath, "reftable"))
	}
	for _, dir := range candidates {
		// Lstat, not Stat: git creates reftable/ as a real directory, so a
		// symlink in its place is not a genuine reftable stack. Lstat inspects
		// the entry itself rather than following the link, so a symlink reports
		// IsDir()==false and is correctly not treated as a reftable repository.
		if info, err := os.Lstat(dir); err == nil && info.IsDir() {
			return true
		}
	}
	return false
}

// reftableStorer adapts a filesystem-backed go-git storage so it can open and
// operate on repositories that use the reftable ref backend. Object, config,
// index, shallow and module storage keep flowing through the embedded
// filesystem storage (reftable only changes ref storage, not object storage);
// the reference-storer methods are overridden to shell out to the git CLI,
// which is the only reftable reader/writer available to us.
//
// It also advertises reftable support via the ExtensionChecker interface so
// go-git's extension verification does not reject the repository on open.
//
// TODO: remove this entire type (and its wiring in repository.go) once go-git
// gains a built-in reftable reader/writer. It exists only because the vendored
// go-git has no reftable backend, so ref operations must shell out to the git
// CLI. When upstream supports reftable natively, the plain filesystem storer
// handles these repositories and this shim can be deleted.
type reftableStorer struct {
	*gitfilesystem.Storage

	gitDir string

	// runGitFn runs a git plumbing command and returns trimmed stdout, raw
	// stderr, and the exec error. It is overridable in tests to simulate
	// spawn/timeout/exit failures deterministically; in production it is nil and
	// runGit dispatches to execGit.
	runGitFn func(args ...string) (string, []byte, error)
}

var (
	_ gogitstorage.Storer = (*reftableStorer)(nil)
	// The concrete methods below satisfy storer.ReferenceStorer, overriding the
	// embedded filesystem implementation.
	_ storer.ReferenceStorer = (*reftableStorer)(nil)
)

// newReftableStorer wraps a filesystem storage with reftable-aware reference
// handling. gitDir must be the repository's git directory (for a linked
// worktree, the worktree's git dir); git resolves the shared reftable stack
// from its commondir automatically.
func newReftableStorer(fs *gitfilesystem.Storage, gitDir string) *reftableStorer {
	return &reftableStorer{Storage: fs, gitDir: gitDir}
}

// SupportsExtension lets go-git open a repository that declares the
// extensions.refstorage=reftable extension, and preserves the embedded
// filesystem storage's support for every other extension it recognises
// (objectformat=sha1/sha256, worktreeconfig).
//
// Defining this method here shadows the promoted *gitfilesystem.Storage
// method, so it must delegate: without the fallback, a reftable repository
// that also declares objectformat=sha256 or worktreeConfig would be rejected
// by go-git's extension verification with ErrUnknownExtension, since it only
// consults the storer's SupportsExtension. Reftable only changes ref storage,
// not object storage, so object-format support is unaffected.
func (s *reftableStorer) SupportsExtension(name, value string) bool {
	if strings.EqualFold(name, "refstorage") {
		return true
	}
	return s.Storage.SupportsExtension(name, value)
}

// runGit runs a git plumbing command scoped to this repository's git dir and
// returns trimmed stdout, raw stderr, and the exec error. Only ref plumbing
// (for-each-ref, symbolic-ref, update-ref, rev-parse) is used, none of which
// trigger git hooks, so this cannot recurse back into entire. Tests may inject
// runGitFn to simulate failures; production dispatches to execGit.
func (s *reftableStorer) runGit(args ...string) (string, []byte, error) {
	if s.runGitFn != nil {
		return s.runGitFn(args...)
	}
	return s.execGit(args...)
}

func (s *reftableStorer) execGit(args ...string) (string, []byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), reftableGitTimeout)
	defer cancel()

	full := append([]string{"--git-dir", s.gitDir}, args...)
	cmd := exec.CommandContext(ctx, "git", full...)
	cmd.Env = gitPlumbingEnv()

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	// On our timeout the process is killed and Run reports the kill as an
	// *exec.ExitError, which would be indistinguishable from a genuine
	// non-zero exit. Re-wrap with the context error so callers (refLookupAbsent)
	// never mistake a wedged git for a definitive "ref not found".
	if err != nil && ctx.Err() != nil {
		err = fmt.Errorf("git %s timed out after %s: %w", strings.Join(args, " "), reftableGitTimeout, ctx.Err())
	}
	return strings.TrimRight(stdout.String(), "\n"), stderr.Bytes(), err
}

// gitPlumbingEnv builds the environment for a reftable git plumbing command.
// LC_ALL=C / LANG=C force untranslated (English) diagnostics so the stderr
// classification (isRefCASConflict, and RemoveReference's idempotency check)
// stays correct on a localized machine — git's error messages are i18n'd, and
// matching translated text would silently misclassify CAS conflicts and delete
// failures. GIT_TERMINAL_PROMPT=0 keeps git non-interactive. The forced values
// are appended last so they override anything the caller's environment set
// (os/exec keeps the last value for a duplicate key). Mirrors the sibling
// shell-out in checkpoint/shadow_ref.go.
func gitPlumbingEnv() []string {
	return append(os.Environ(),
		"GIT_TERMINAL_PROMPT=0",
		"LC_ALL=C",
		"LANG=C",
	)
}

// refLookupAbsent reports whether a failed ref lookup (rev-parse --verify
// --quiet, update-ref) means the reference is genuinely absent rather than a
// failure to consult git at all. Only genuine absence may map to the
// plumbing.ErrReferenceNotFound / idempotent-delete sentinels; a spawn failure,
// timeout, or I/O error must be surfaced so a transient git failure is never
// mistaken for a missing ref (which would let the strategy orphan a checkpoint
// ref or drop a link).
//
// git ran and reported absence iff it exited non-zero AND stayed silent: under
// --quiet a missing ref produces no error output, whereas a fatal/I/O failure
// exits non-zero with a "fatal: ..." message, and a spawn failure or our
// timeout is not an *exec.ExitError at all.
func refLookupAbsent(err error, stderr []byte) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
		return false
	}
	var exitErr *exec.ExitError
	if !errors.As(err, &exitErr) {
		return false
	}
	return len(bytes.TrimSpace(stderr)) == 0
}

// SetReference stores a reference, dispatching to symbolic-ref for symbolic
// references and update-ref for hash references.
func (s *reftableStorer) SetReference(ref *plumbing.Reference) error {
	if ref == nil {
		return nil
	}
	if ref.Type() == plumbing.SymbolicReference {
		if _, stderr, err := s.runGit("symbolic-ref", "--end-of-options", ref.Name().String(), ref.Target().String()); err != nil {
			return fmt.Errorf("reftable set symbolic ref %s: %s: %w", ref.Name(), strings.TrimSpace(string(stderr)), err)
		}
		return nil
	}
	if _, stderr, err := s.runGit("update-ref", "--end-of-options", ref.Name().String(), ref.Hash().String()); err != nil {
		return fmt.Errorf("reftable set ref %s: %s: %w", ref.Name(), strings.TrimSpace(string(stderr)), err)
	}
	return nil
}

// CheckAndSetReference performs a compare-and-swap update. When old is non-nil
// the update is conditioned on the current value, mirroring go-git's atomic
// semantics; a genuine mismatch is reported as storage.ErrReferenceHasChanged.
//
// Only a real compare-and-swap conflict maps to that sentinel. Callers such as
// strategy.atomicSetV1Ref treat ErrReferenceHasChanged as "another worktree
// advanced the ref" and abort the push as a concurrency event, while wrapping
// every other error as a genuine failure. Mapping an unrelated failure (bad
// object, invalid ref name, lock contention, timeout, git spawn failure) to the
// conflict sentinel would misreport a storage error as a benign race, so those
// are surfaced as themselves.
func (s *reftableStorer) CheckAndSetReference(newRef, old *plumbing.Reference) error {
	if newRef == nil {
		return nil
	}
	if newRef.Type() == plumbing.SymbolicReference {
		// Symbolic refs (e.g. HEAD) have no CAS form in update-ref; set directly.
		return s.SetReference(newRef)
	}
	if old == nil {
		return s.SetReference(newRef)
	}
	_, stderr, err := s.runGit("update-ref", "--end-of-options", newRef.Name().String(), newRef.Hash().String(), old.Hash().String())
	if err == nil {
		return nil
	}
	if IsRefCASConflict(stderr) {
		return gogitstorage.ErrReferenceHasChanged
	}
	return fmt.Errorf("reftable CAS ref %s: %s: %w", newRef.Name(), strings.TrimSpace(string(stderr)), err)
}

// IsRefCASConflict reports whether git update-ref stderr indicates a
// compare-and-swap conflict: the stored value was not the expected old value
// ("... is at X but expected Y"), or a create-if-absent update found the ref
// already present ("reference already exists"). These are the only failures
// that mean the reference changed concurrently. Object/name/lock/spawn errors
// carry different messages and must not be misclassified as conflicts.
func IsRefCASConflict(stderr []byte) bool {
	msg := strings.ToLower(string(stderr))
	return strings.Contains(msg, "but expected") ||
		strings.Contains(msg, "reference already exists")
}

// Reference returns the reference with the given name, preserving symbolic refs
// (such as HEAD) so go-git can resolve them itself.
func (s *reftableStorer) Reference(name plumbing.ReferenceName) (*plumbing.Reference, error) {
	// Symbolic refs: symbolic-ref exits 0 and prints the target only for a
// Pre-push OPF rewrite for the git-refs checkpoint backend, the sibling of
// manual_commit_opf_rewrite.go's entire/checkpoints/v1 rewrite. Both run the
// OPF-augmented redaction once per push; only discovery and ref update differ.
package strategy

import (
	"context"
	"errors"
	"fmt"
	"slices"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/entireio/cli/redact"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// RewriteQueuedCheckpointRefsWithOPF re-redacts the checkpoint refs awaiting
// push with OPF, rebuilds every un-applied commit on each as a commit carrying
// Entire-OPF-Applied: true, and points the ref at the new tip. Idempotent: a
// ref whose tip already carries the trailer is left byte-identical.
//
// Discovery is the push-discovery queue rather than a local-vs-remote diff: it
// already names exactly the refs this push will carry, so there is no
// merge-base or divergence analysis. Within a ref, pushing it carries its whole
// unpushed ancestry, so the walk covers every commit back to the first one
// already carrying the trailer (unappliedAncestry) — bounded by the same
// resolveBootstrapLimit the v1 path uses.
//
// Caller checks redact.OPFEnabled() and skips this when OPF is off. Returns
// the same error taxonomy as RewriteUnpushedV1WithOPF; the caller fails closed
// by withholding the flush (see prePushCheckpointRefs).
func RewriteQueuedCheckpointRefsWithOPF(ctx context.Context, repo *git.Repository) error {
	queue, err := checkpoint.PushQueueForRepo(ctx, repo)
	if err != nil {
		return fmt.Errorf("resolve push queue: %w", err)
	}
	// Peek, not Drain: flushCheckpointRefsQueue owns draining and pruning.
	queued, err := queue.Peek()
	if err != nil {
		return fmt.Errorf("peek push queue: %w", err)
	}
	if len(queued) == 0 {
		return nil
	}

	// Both up-front fail-closed gates, in the same order as the v1 rewrite, so
	// a misconfigured category set surfaces config remediation rather than
	// "verify your OPF install".
	if redact.OPFMisconfiguredNoCategories() {
		return &OPFNoCategoriesError{}
	}
	if redact.OPFBreakerTripped() {
		return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
	}

	// Pass 1: collect every redactable blob from every un-applied commit on every
	// queued ref, bounding raw bytes in memory exactly as the v1 collect pass
	// does — cumulatively across the whole flush, not per ref.
	type pendingCommit struct {
		commit *object.Commit
		// blobs and paths are parallel; startIdx is this commit's offset into
		// the global redacted slice.
		blobs    []redact.NamedBlob
		paths    []string
		startIdx int
	}
	type pendingRef struct {
		ref plumbing.ReferenceName
		old plumbing.Hash
		// base is the parent the deepest rewritten commit keeps.
		base    plumbing.Hash
		commits []pendingCommit // ancestor-first
	}
	var globalBlobs []redact.NamedBlob
	pendings := make([]pendingRef, 0, len(queued))
	rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
	bootstrapLimit := resolveBootstrapLimit()
	var rawBytesSoFar int
	// Stale entries (refs no longer present locally) are skipped, not pruned:
	// the queue belongs to the flush.
	existing, _ := partitionLocalRefs(repo, queued)
	for _, refName := range existing {
		ref, refErr := repo.Reference(refName, true)
		if refErr != nil {
			if errors.Is(refErr, plumbing.ErrReferenceNotFound) {
				continue
			}
			return fmt.Errorf("resolve checkpoint ref %s: %w", refName, refErr)
		}
		chain, base, walkErr := unappliedAncestry(repo, ref.Hash())
		if walkErr != nil {
			return fmt.Errorf("walk ancestry of %s: %w", refName, walkErr)
		}
		if len(chain) == 0 {
			continue
		}
		if len(chain) > bootstrapLimit {
			return &BootstrapTooLargeError{Count: len(chain), Limit: bootstrapLimit}
		}
		pr := pendingRef{ref: refName, old: ref.Hash(), base: base}
		for _, c := range chain {
			tree, treeErr := repo.TreeObject(c.TreeHash)
			if treeErr != nil {
				return fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], treeErr)
			}
			pc := pendingCommit{commit: c, startIdx: len(globalBlobs)}
			if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
				return fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
			}
			for _, b := range pc.blobs {
				rawBytesSoFar += len(b.Content)
			}
			if rawBytesSoFar > rawCap {
				return &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
			}
			globalBlobs = append(globalBlobs, pc.blobs...)
			pr.commits = append(pr.commits, pc)
		}
		pendings = append(pendings, pr)
	}
	if len(pendings) == 0 {
		return nil
	}

	// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF shell-out
	// for the whole flush.
	var globalRedacted [][]byte
	if len(globalBlobs) > 0 {
		leafBytes := redact.SumProseLeafBytes(globalBlobs)
		if limit := resolveBatchLimit(); leafBytes > limit {
			return &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
		}
		globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
		if err != nil {
			if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
				return &OPFNoCategoriesError{}
			}
			return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
		}
	}

	// Pass 3: rebuild every commit before touching any ref, so a failure
	// part-way through leaves every ref where it was. Each ref's chain is
	// replayed ancestor→tip, so the rewritten parent carries into the next
	// commit and the deepest one keeps the boundary parent.
	rebuilt := make([]plumbing.Hash, len(pendings))
	for i, pr := range pendings {
		parent := pr.base
		for _, pc := range pr.commits {
			redactedByPath := make(map[string][]byte, len(pc.blobs))
			for j, path := range pc.paths {
				redactedByPath[path] = globalRedacted[pc.startIdx+j]
			}
			newHash, rebuildErr := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
			if rebuildErr != nil {
				return fmt.Errorf("rebuild checkpoint commit %s on %s: %w", pc.commit.Hash.String()[:7], pr.ref, rebuildErr)
			}
			parent = newHash
		}
		rebuilt[i] = parent
	}

	// CAS each ref: a concurrent write that advanced a checkpoint ref during
	// the rewrite must not be clobbered by our stale rebuild.
	for i, pr := range pendings {
		if err := checkpoint.CASPersistentRef(ctx, repo, pr.ref, rebuilt[i], pr.old); err != nil {
			return fmt.Errorf("update checkpoint ref %s: %w", pr.ref, err)
		}
	}
	return nil
}

// unappliedAncestry walks first parents back from a checkpoint ref's tip and
// returns the commits that do not carry the OPF trailer, ancestor-first, plus
// the parent the deepest one keeps: the trailered commit the walk stopped at,
// or zero at a root. Checkpoint refs are a single-parent chain, so the first
// parent is the whole history.
func unappliedAncestry(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, plumbing.Hash, error) {
	var chain []*object.Commit
	base := plumbing.ZeroHash
	for h := tip; !h.IsZero(); {
		c, err := repo.CommitObject(h)
		if err != nil {
			return nil, plumbing.ZeroHash, fmt.Errorf("load commit %s: %w", h.String()[:7], err)
		}
		if trailers.HasOPFApplied(c.Message) {
			base = h
			break
		}
		chain = append(chain, c)
		if len(c.ParentHashes) == 0 {
			break
		}
		h = c.ParentHashes[0]
	}
	slices.Reverse(chain)
	return chain, base, nil
}

	for _, d := range deferredHashes {
		if newFullJSONLHash.IsZero() {
			continue // no transcript in this dir; keep original hash
		}
		jsonlBytes, err := readBlob(repo, newFullJSONLHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("read new transcript for content_hash: %w", err)
		}
		sum := sha256.Sum256(jsonlBytes)
		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(fmt.Sprintf("sha256:%x", sum)))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("write content_hash: %w", err)
		}
		entries[d.idx] = object.TreeEntry{Name: d.entryName, Mode: d.entryMode, Hash: hashBlob}
	}

	newTree := &object.Tree{Entries: entries}
	obj := repo.Storer.NewEncodedObject()
	if err := newTree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode tree: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("store tree: %w", err)
	}
	return hash, nil
}

func readBlob(repo *git.Repository, hash plumbing.Hash) ([]byte, error) {
	blob, err := repo.BlobObject(hash)
	if err != nil {
		return nil, fmt.Errorf("blob: %w", err)
	}
	r, err := blob.Reader()
	if err != nil {
		return nil, fmt.Errorf("blob reader: %w", err)
	}
	defer func() { _ = r.Close() }()
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("blob read: %w", err)
	}
	return data, nil
}

// atomicSetV1Ref CAS-updates the local v1 ref through the same lock protocol as
// checkpoint writers. A busy ref means another writer may have advanced it, so
// return V1RefMovedError and abort the push rather than reuse the stale rewrite.
func atomicSetV1Ref(ctx context.Context, repo *git.Repository, expectedOld, newHash plumbing.Hash) error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	err := checkpoint.CASPersistentRef(ctx, repo, refName, newHash, expectedOld)
	if err == nil {
		return nil
	}
	if errors.Is(err, checkpoint.ErrShadowRefBusy) {
		actual := plumbing.ZeroHash
		if cur, refErr := repo.Reference(refName, true); refErr == nil {
			actual = cur.Hash()
		}
		return &V1RefMovedError{Expected: expectedOld, Actual: actual}
	}
	return fmt.Errorf("set v1 ref: %w", err)
}

