package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"

	"github.com/go-git/go-git/v6/plumbing"
)

// ErrShadowRefBusy is returned by casUpdateShadowBranchRef when the ref has
// moved since the caller read it. Callers retry with a fresh parent.
var ErrShadowRefBusy = errors.New("shadow branch ref moved (CAS mismatch)")

// shadowRefMaxRetries bounds the WriteTemporary retry loop. With the
// per-shadow-branch flock held, our own writers never collide; this budget
// is purely a safety net against an external `git update-ref` writer that
// repeatedly beats us to the ref.
const shadowRefMaxRetries = 16

// shadowRefMaxJitter is the upper bound for randomized backoff between CAS
// retries. Random jitter avoids thundering-herd retry patterns when many
// sessions hit the same shadow branch simultaneously.
const shadowRefMaxJitter = 8 * time.Millisecond

// repoDirs returns the worktree root and git common dir for the store's
// repository. Callers use the worktree root as cmd.Dir for git invocations
// and the common dir to locate filesystem paths (lock files, loose objects)
// — both without depending on the process cwd.
func (s *ephemeralStore) repoDirs(ctx context.Context) (worktreeRoot, commonDir string, err error) {
	return repositoryDirs(ctx, s.repo)
}

// casUpdateShadowBranchRef atomically updates a shadow branch ref via
// `git update-ref <ref> <new> <old>`. Pass plumbing.ZeroHash as expectedHash
// to require the ref to NOT exist (first-checkpoint case).
//
// repoRoot is used as cmd.Dir so the update targets the same repository as
// the rest of WriteTemporary (i.e. s.repo) regardless of the process cwd.
//
// Returns ErrShadowRefBusy when git reports the ref moved since expectedHash
// was observed; callers retry with a fresh parent. Any other failure is
// returned wrapped.
//
// Why shell out: git's ref-locking is the canonical cross-process atomic
// CAS — go-git's CheckAndSetReference doesn't interoperate with native git's
// .lock files, and shadow branches can be touched concurrently by separate
// `entire` hook processes.
func casUpdateShadowBranchRef(ctx context.Context, repoRoot, branchName string, newHash, expectedHash plumbing.Hash) error {
	return casUpdateRef(ctx, repoRoot, plumbing.NewBranchReferenceName(branchName), newHash, expectedHash)
}

// shadowRefBackoff sleeps for a small random jitter before the next CAS
// retry. After several retries the upper bound doubles to slow the
// thundering herd further. Respects context cancellation.
func shadowRefBackoff(ctx context.Context, attempt int) error {
	base := shadowRefMaxJitter
	if attempt > 4 {
		base *= 2
	}
	// Add a 1ms floor so the chosen sleep is always non-trivial, even when
	// rand.Int64N happens to return 0.
	d := time.Duration(rand.Int64N(int64(base))) + time.Millisecond //nolint:gosec // jitter, not security-sensitive
	select {
	case <-time.After(d):
		return nil
	case <-ctx.Done():
		return ctx.Err() //nolint:wrapcheck // canonical context cancellation
	}
}

// shadowBranchLockPath returns the per-shadow-branch flock file path. Lock
// files live in <git-common-dir>/entire-shadow-locks/ so they don't pollute
// the session-state directory. Branch names are slash-escaped because the
// shadow-branch convention "entire/<hash>" would otherwise nest directories.
func shadowBranchLockPath(commonDir, branchName string) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-shadow-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create shadow lock directory: %w", err)
	}
	safe := strings.ReplaceAll(branchName, "/", "_")
	return filepath.Join(lockDir, safe+".lock"), nil
}

// withShadowBranchFlock acquires the per-shadow-branch flock, runs fn, and
// releases the flock. Serializes all WriteTemporary callers that target the
// same shadow branch — across goroutines AND across processes — so the CAS
// in casUpdateShadowBranchRef only sees external writers as contention.
//
// commonDir is the git common directory (from s.repoDirs); it locates the
// lock file independently of the process cwd.
func withShadowBranchFlock(commonDir, branchName string, fn func() error) error {
	path, err := shadowBranchLockPath(commonDir, branchName)
	if err != nil {
		return err
	}
	release, err := flock.Acquire(path)
	if err != nil {
		return fmt.Errorf("acquire shadow flock %s: %w", branchName, err)
	}
	defer release()
	return fn()
}

// tryDeleteLooseObject best-effort removes a loose object file. Used to
// clean up dangling commits created during a CAS-losing attempt. Failures
// (e.g. object already packed by a concurrent gc, or never written as a
// loose object) are ignored — the object will be picked up by the next gc
// pass either way.
func tryDeleteLooseObject(commonDir string, hash plumbing.Hash) {
	h := hash.String()
	if len(h) < 3 {
		return
	}
	_ = os.Remove(filepath.Join(commonDir, "objects", h[:2], h[2:]))
}
package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strconv"
	"sync"
	"time"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

// ListHydrationTimeout is the per-ref budget for hydrating names-only List stubs
// during user-facing enumeration (after the display-limit truncate). Shorter than
// the default on-demand fetch budget so a stuck remote cannot turn list/explain
// into many minutes of sequential ref fetches.
const ListHydrationTimeout = 15 * time.Second

// ListHydrationPassTimeout bounds the entire List/explain stub-hydration pass.
// Without this, a slow remote can burn stub_count * ListHydrationTimeout
// (limit defaults to 100 and is user-settable via --limit).
const ListHydrationPassTimeout = 30 * time.Second

var (
	_ PersistentStore = (*gitRefsStore)(nil)
	_ AuthorReader    = (*gitRefsStore)(nil)
	_ Writer          = (*gitRefsStore)(nil)
)

// gitRefsStore is the git-backed persistent checkpoint store that keeps one ref
// per checkpoint at refs/entire/checkpoints/<shard>/<id>. Each ref points at a
// commit whose tree root IS that checkpoint's contents (metadata.json, 0/, 1/,
// tasks/…), so updates advance the ref and preserve per-checkpoint history. It
// shares the checkpoint-subtree machinery with the git-branch store via the
// embedded *treeWriter (anchored at basePath ""), differing only in where the
// subtree is committed: a per-checkpoint ref instead of the v1 branch.
type gitRefsStore struct {
	*treeWriter

	blobFetcher     BlobFetchFunc
	refFetcher      RefFetchFunc
	remoteRefLister RemoteRefListFunc

	// fetchFailureMu guards fetchFailure: the first transport-level ref-fetch
	// failure, memoized for the store's lifetime so a loop over N missing refs
	// (e.g. a stop hook finalizing every checkpoint of a turn) pays a dead —
	// or too-slow-for-the-budget — network once instead of N times. Genuine
	// remote absence is per-ref and
	// is never memoized. The memo never clears — safe because every
	// fetcher-wired store today is opened per command/hook invocation; a
	// long-lived fetcher-wired store would need an expiry before reusing this.
	fetchFailureMu sync.Mutex
	fetchFailure   error
}

// newGitRefsStore constructs the per-checkpoint-ref store for a repository.
func newGitRefsStore(repo *git.Repository) *gitRefsStore {
	return &gitRefsStore{treeWriter: &treeWriter{repo: repo}}
}

// SetBlobFetcher configures on-demand blob fetching for reads from ref trees.
func (s *gitRefsStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// SetRefFetcher configures on-demand fetching of a missing checkpoint ref (e.g.
// a checkpoint written on another machine). nil leaves reads local-only.
func (s *gitRefsStore) SetRefFetcher(f RefFetchFunc) {
	s.refFetcher = f
}

// SetRemoteRefLister configures remote checkpoint-ref enumeration for List (see
// RemoteRefListFunc). It only takes effect when List is called on a context
// marked by WithRemoteListDiscovery, so the per-turn hook hot path — which
// lists local refs without opting in — never triggers a network round trip. nil
// leaves List local-only.
func (s *gitRefsStore) SetRemoteRefLister(f RemoteRefListFunc) {
	s.remoteRefLister = f
}

// remoteListDiscoveryKey marks a context as permitting List to enumerate the
// checkpoint remote. It is an unexported key type so only this package can set
// or read the marker.
type remoteListDiscoveryKey struct{}

// WithRemoteListDiscovery marks ctx to allow gitRefsStore.List to enumerate
// checkpoint refs on the configured checkpoint remote (see RemoteRefListFunc)
// and surface not-yet-local checkpoints. Set it only on explicit, user-facing
// enumeration flows (e.g. `entire checkpoint list` / the branch `explain`
// view), never on the per-turn commit hook: routine local listings must stay
// network-free. Without this marker List is local-only regardless of whether a
// remote lister is configured.
func WithRemoteListDiscovery(ctx context.Context) context.Context {
	return context.WithValue(ctx, remoteListDiscoveryKey{}, true)
}

// remoteListDiscoveryEnabled reports whether ctx was marked via
// WithRemoteListDiscovery.
func remoteListDiscoveryEnabled(ctx context.Context) bool {
	v, ok := ctx.Value(remoteListDiscoveryKey{}).(bool)
	return ok && v
}

// Write dispatches a persistent write request to the matching ref operation,
// mirroring the git-branch store's Write.
func (s *gitRefsStore) Write(ctx context.Context, req WriteRequest) error {
	switch r := req.(type) {
	case Session:
		return s.writeSession(ctx, WriteOptions(r))
	case ReservedSession:
		return s.writeSession(ctx, WriteOptions(r))
	case SessionTranscript:
		return s.backfillTranscript(ctx, UpdateOptions(r))
	case SessionSummary:
		return s.backfillSummary(ctx, r.CheckpointID, r.Summary)
	case CheckpointAttribution:
		return s.backfillAttribution(ctx, r.CheckpointID, r.Attribution)
	default:
		return fmt.Errorf("checkpoint: unsupported write request %T", req)
	}
}

// refBase resolves a checkpoint ref's current tip commit (the parent for the
// next write) and subtree object (the checkpoint's current contents) with a
// LOCAL-ONLY lookup. A missing ref yields (ZeroHash, nil) so the next write
// becomes an orphan commit — correct for creates, whose ref never exists yet
// (locally or remotely); probing the remote would add a doomed round-trip to
// every condensation and, with a fetcher configured, fail offline writes.
// Backfills, which target an existing checkpoint, use refBaseForBackfill
// instead. Migration (migrate.go) also uses refBase deliberately: it imports
// from the LOCAL v1 branch and must never probe the remote, even though its
// target ref may already exist. One writeSession caller does target an
// existing checkpoint — attach, which adds a session to it — but attach
// pre-fetches and verifies the ref's presence itself (refreshCheckpoint)
// before writing, so the local-only probe is safe there too.
func (s *gitRefsStore) refBase(cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
	refName, err := RefName(cid)
	if err != nil {
		return plumbing.ZeroHash, nil, err
	}
	ref, err := s.repo.Reference(refName, true)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		return plumbing.ZeroHash, nil, nil // no ref yet → new checkpoint (orphan)
	}
	if err != nil {
		// A real lookup failure (IO/corruption), not an absent ref: surface it
		// rather than silently starting a fresh orphan history over the ref.
		return plumbing.ZeroHash, nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
	}
	return s.refTip(cid, ref)
}

// refBaseForBackfill resolves like refBase, but a ref missing locally is
// first fetched once from the remote (resolveRefMaybeFetch) when a fetcher is
// configured: a backfill targets an EXISTING checkpoint that may have been
// written or migrated on another machine, and declaring it absent without
// looking remotely diverges from the read path — the backfill would be
// handled as targeting a nonexistent checkpoint while reads, which DO fetch,
// serve the refs copy, leaving the backfilled data permanently invisible.
// A ref absent even after the fetch yields (ZeroHash, nil), which the
// backfill helpers report as ErrCheckpointNotFound — the signal that the
// checkpoint does not exist in this backend. A fetch FAILURE is returned
// as-is: transient unavailability must never masquerade as absence, because
// a caller or routing layer acting on a false "absent" would misdirect the
// backfill (e.g. onto a stale copy in another backend) instead of retrying.
func (s *gitRefsStore) refBaseForBackfill(ctx context.Context, cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
	ref, err := s.resolveRefMaybeFetch(ctx, cid)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		return plumbing.ZeroHash, nil, nil // genuinely absent → backfill reports not-found
	}
	if err != nil {
		return plumbing.ZeroHash, nil, err
	}
	return s.refTip(cid, ref)
}

// refTip reads the commit and tree at a resolved checkpoint ref.
func (s *gitRefsStore) refTip(cid id.CheckpointID, ref *plumbing.Reference) (plumbing.Hash, *object.Tree, error) {
	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
	}
	return ref.Hash(), tree, nil
}

// enqueueForPush records refName in the push-discovery queue, logging (never
// returning) on failure so the local ref write still succeeds.
//
// The queue is resolved with the cancellation stripped from ctx. By the time we
// get here the ref is already written locally, and the queue is the ONLY
// push-discovery mechanism there is — see the
// pushQueueFileName doc. A ref that misses the queue is never pushed, and the
// writers above are idempotent, so a re-run skips it as already-present and
// never re-enqueues it: it stays local-only forever. Resolving the queue shells
// out to `git rev-parse --git-common-dir`, which fails instantly on a canceled
// ctx, so honoring cancellation here would drop the bookkeeping for a write
// that already happened. This local, sub-millisecond step therefore completes
// even during shutdown (a second Ctrl-C still force-quits the process).
func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
	q, err := PushQueueForRepo(context.WithoutCancel(ctx), s.repo)
	if err != nil {
		logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
		return
	}
	if err := q.Enqueue(refName); err != nil {
		logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
	}
}

func (s *gitRefsStore) updateCheckpointRef(
	ctx context.Context,
	cid id.CheckpointID,
	base func() (plumbing.Hash, *object.Tree, error),
	build func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error),
) error {
	refName, err := RefName(cid)
	if err != nil {
		return err
	}
	err = updatePersistentRef(ctx, s.repo, refName, func() (plumbing.Hash, plumbing.Hash, error) {
		parentHash, existing, baseErr := base()
		if baseErr != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, baseErr
		}
		newHash, buildErr := build(parentHash, existing)
		return newHash, parentHash, buildErr
	})
	if err != nil {
		return err
	}
	s.enqueueForPush(ctx, refName)
	return nil
}

func (s *gitRefsStore) writeSession(ctx context.Context, opts WriteOptions) error {
	// Parity with the backfill writers above and with GitStore.writeSession: a
	// canceled ctx means stop doing work, and creating a checkpoint is the most
	// expensive write there is (tree building plus a commit). Without this a
	// bulk writer that ignores cancellation — `entire import` was one — keeps
	// minting checkpoints after Ctrl-C.
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid checkpoint options: checkpoint ID is required")
	}
	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	return s.updateCheckpointRef(ctx, opts.CheckpointID,
		func() (plumbing.Hash, *object.Tree, error) {
			return s.refBase(opts.CheckpointID)
		},
		func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error) {
			checkpointSubtree, err := s.applySessionWrite(ctx, opts, existing, "")
			if err != nil {
				return plumbing.ZeroHash, err
			}
			commitMsg := s.buildCommitMessage(opts)
			return CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
		},
	)
}

func (s *gitRefsStore) backfillTranscript(ctx context.Context, opts UpdateOptions) error {
package checkpoint

import (
	"context"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

var (
	_ PersistentStore = (*GitStore)(nil)
	_ AuthorReader    = (*GitStore)(nil)
	_ Writer          = (*GitStore)(nil)
	_ EphemeralStore  = (*ephemeralStore)(nil)
)

// treeWriter holds the repo-only machinery for building a single checkpoint's
// subtree from write requests: entry builders, transcript/session writers, and
// the per-request appliers (applySessionWrite / applyTranscriptBackfill /
// applySummaryBackfill / applyAttributionBackfill). It is independent of where
// the resulting subtree is committed, so both the git-branch store (which nests
// the subtree under <shard>/<id>/ on the v1 branch) and the git-refs store
// (which keeps it at the root of a per-checkpoint ref) embed it and share this
// code.
type treeWriter struct {
	repo *git.Repository
}

// GitStore is the committed (persistent) checkpoint store. Writes target
// refs.Primary; committed reads resolve against refs.Read. The temporary
// shadow-branch surface lives in ephemeralStore. It embeds *treeWriter for the
// shared subtree-building machinery.
type GitStore struct {
	*treeWriter

	refs                  PersistentRefs
	blobFetcher           BlobFetchFunc
	metadataBranchFetcher MetadataBranchFetchFunc
	// metadataBranchFetchTried latches the one recovery attempt per store; see
	// tryFetchMetadataBranch.
	metadataBranchFetchTried bool
	// readRemotes is the ordered checkpoint read-candidate chain consulted by
	// committed reads after the local tree; see OpenOptions.ReadRemotes. nil
	// means the legacy origin-only fallback.
	readRemotes []string
}

// ephemeralStore is the git shadow-branch (temporary) checkpoint store. It is
// an independent type from GitStore; the two share only package-level helpers.
type ephemeralStore struct {
	repo *git.Repository
	refs PersistentRefs
}

// newEphemeralStore creates the shadow-branch store for the given repository
// and committed-metadata topology (it consults refs.Primary to recognize the
// committed branch when listing shadow branches).
func newEphemeralStore(repo *git.Repository, refs PersistentRefs) *ephemeralStore {
	return &ephemeralStore{repo: repo, refs: refs}
}

// NewEphemeralStore constructs the git shadow-branch (temporary) checkpoint
// store. Most callers reach it via Open(...).Ephemeral(); this direct
// constructor exists for benchmarks and tests that exercise the shadow-branch
// surface without the full facade.
func NewEphemeralStore(repo *git.Repository, refs PersistentRefs) EphemeralStore {
	return newEphemeralStore(repo, refs)
}

// NewGitStore creates a checkpoint store backed by the given git repository
// and committed-metadata topology. Pass DefaultV1Refs() for the v1-only default
// or ResolveRefs(ctx) in code paths that honor settings.
func NewGitStore(repo *git.Repository, refs PersistentRefs) *GitStore {
	return &GitStore{treeWriter: &treeWriter{repo: repo}, refs: refs}
}

// SetBlobFetcher configures the store to automatically fetch missing blobs
// on demand when reading from metadata trees.
func (s *GitStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// SetReadRemotes configures the ordered checkpoint read-candidate remotes
// (elected sync remote first, then the legacy origin tier) whose tracking
// refs committed reads consult after the local tree. Selection happens by
// requested checkpoint, so an existing but incomplete tree does not mask a
// later candidate. This is a pure read — the chain never seeds or advances
// local refs. nil keeps the legacy origin-only fallback.
func (s *GitStore) SetReadRemotes(remotes []string) {
	s.readRemotes = remotes
}

// SetMetadataBranchFetcher configures the store to fetch the metadata branch
// from the checkpoint remote when it is missing both locally and on origin.
// See MetadataBranchFetchFunc for when it is appropriate to wire this.
func (s *GitStore) SetMetadataBranchFetcher(f MetadataBranchFetchFunc) {
	s.metadataBranchFetcher = f
}

// Repository returns the underlying git repository.
func (s *GitStore) Repository() *git.Repository {
	return s.repo
}

// Refs returns the committed-metadata topology the store was constructed with.
func (s *GitStore) Refs() PersistentRefs {
	return s.refs
}

// PersistentReadRef returns the ref that committed-checkpoint reads resolve against.
func (s *GitStore) PersistentReadRef() plumbing.ReferenceName {
	return s.refs.Read
}

func (s *GitStore) updatePrimaryRef(ctx context.Context, build func(parentHash, rootTreeHash plumbing.Hash) (plumbing.Hash, error)) error {
	return updatePersistentRef(ctx, s.repo, s.refs.Primary, func() (plumbing.Hash, plumbing.Hash, error) {
		parentHash, rootTreeHash, err := s.getSessionsBranchRef()
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, err
		}
		newHash, buildErr := build(parentHash, rootTreeHash)
		return newHash, parentHash, buildErr
	})
}
