		current := ref.Hash()
		if calls == 1 {
			commit, err := repo.CommitObject(current)
			if err != nil {
				return plumbing.ZeroHash, plumbing.ZeroHash, err
			}
			external, err := CreateCommit(ctx, repo, commit.TreeHash, current, "external writer", "Test", "test@test.com")

